    8006  .db C2 17 02 54 45 4C 45 54 45 58 54 00 32 2E 35 30  ; ...TELETEXT.2.50
    8016  .db 0D 00 28 43 29 42 42 43 20 31 39 38 36 00        ; ..(C)BBC 1986.
;------------------------------------------------------------------------------
; PAGED ROM SERVICE ENTRY  (A = service call, X = ROM number, Y = parameter)
; Unlike TFS 1.03 there is no dispatch table: each call is tested in turn.
;   &FF       Tube initialisation: hide the language flag (see below)
;   4         unrecognised * command
;   9         *HELP
;   8         OSWORD (&7A)
;   5         interrupt: the page grabber
;   2         private workspace (model B / B+)
;   &22, &24  private workspace in hidden RAM (Master 128)
;   &27       reset (Master)
; After *NOTTX (bit 7 of the workspace byte set) only service 3 and &FF do anything.
; There is no auto-boot handling: ATS is not a filing system.
;------------------------------------------------------------------------------
.service_entry
    8024  08        PHP                     ; P and A are saved; every exit restores them (L81DF)
    8025  48        PHA
    8026  C9 FF     CMP #&FF                ; Tube initialisation?
    8028  D0 2C     BNE L8056
.L802A
